// Sends a payment failure alert to Slack.
// The webhook URL comes from the SLACK_WEBHOOK_URL environment variable.
// It is never logged or included in error messages.

async function sendPaymentFailureAlert({ paymentId, amount, currency, reason }) {
  const url = process.env.SLACK_WEBHOOK_URL;
  if (!url) {
    console.warn('SLACK_WEBHOOK_URL is not set; skipping payment failure alert.');
    return { sent: false, reason: 'not_configured' };
  }

  const text = `Payment failed: ${paymentId} for ${amount} ${currency}. Reason: ${reason}`;

  try {
    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text }),
    });
    if (!res.ok) {
      console.error(`Slack alert failed with HTTP ${res.status}.`);
      return { sent: false, reason: 'http_error' };
    }
    return { sent: true };
  } catch (err) {
    // Do not log err.message blindly; it may include the URL.
    console.error('Slack alert failed: network error.');
    return { sent: false, reason: 'network_error' };
  }
}

module.exports = { sendPaymentFailureAlert };
```

